-- Trivia arcade. Independent of actor scores and movie ratings.
begin;
-- BEGIN GENERATED TRIVIA NICKNAME POLICY
-- Generated by scripts/sync-trivia-nickname-policy.mjs; edit src/lib/trivia-nickname.ts.
create or replace function public.is_trivia_nickname_allowed(p_name text)
returns boolean language plpgsql immutable set search_path = '' as $$
declare
 folded text := lower(normalize(coalesce(p_name, ''), NFKD));
 candidate text;
 compact text;
 collapsed text;
begin
 folded := regexp_replace(folded, U&'[\0300-\036f]', '', 'g');
 foreach candidate in array array[folded, translate(folded, '01345789@!$+€аɑαеεіιоοрρсϲхχуυһнтτкκмμвβ', 'oieastbgaisteaaaeeiiooppccxxyyhhttkkmmbb')] loop
  compact := regexp_replace(candidate, '[^a-z0-9]', '', 'g');
  compact := regexp_replace(compact, '^[0-9x]+|[0-9x]+$', '', 'g');
  collapsed := regexp_replace(compact, '([a-z])\1+', '\1', 'g');
  if compact ~ 'hitler|pelotud|bolud|chupapij|chupaverg|comepij|hij[oa]deputa|putamadre|conchadetumadre|conchadesumadre|siegheil' or collapsed ~ 'hitler|pelotud|bolud|chupapij|chupaverg|comepij|hij[oa]deputa|putamadre|conchadetumadre|conchadesumadre|siegheil'
   or candidate ~ '(^|[^a-z])(pij(a|as|ita|itas|on|ones|udo|uda)|conchas?|put(a|o|as|os|ita|ito|itas|itos|azo|azos|on|ona|ones)|porongas?|vergas?|chot[ao]s?|cul[oa]s?|mierdas?|carajos?|for{2,}[oa]s?|pajer[oa]s?|mogolic[oa]s?|maric(on|ones)|trol[oa]s?|culiad[oa]s?|culead[oa]s?|pendej[oa]s?|gilipol{2,}as|cabron(es)?|nazis?|nazistas?|fuck(er|ing)?|shit|bitch)([^a-z]|$)'
   or compact ~ '^(soy|el|la|un|una|re|gran|capitan|sr|don|mister|the|super|mega|cine)*(pij(a|as|ita|itas|on|ones|udo|uda)|conchas?|put(a|o|as|os|ita|ito|itas|itos|azo|azos|on|ona|ones)|porongas?|vergas?|chot[ao]s?|cul[oa]s?|mierdas?|carajos?|for{2,}[oa]s?|pajer[oa]s?|mogolic[oa]s?|maric(on|ones)|trol[oa]s?|culiad[oa]s?|culead[oa]s?|pendej[oa]s?|gilipol{2,}as|cabron(es)?|nazis?|nazistas?|fuck(er|ing)?|shit|bitch)(pro|gamer|master|rey|cine)*$'
   or collapsed ~ '^(soy|el|la|un|una|re|gran|capitan|sr|don|mister|the|super|mega|cine)*(pij(a|as|ita|itas|on|ones|udo|uda)|conchas?|put(a|o|as|os|ita|ito|itas|itos|azo|azos|on|ona|ones)|porongas?|vergas?|chot[ao]s?|cul[oa]s?|mierdas?|carajos?|for{2,}[oa]s?|pajer[oa]s?|mogolic[oa]s?|maric(on|ones)|trol[oa]s?|culiad[oa]s?|culead[oa]s?|pendej[oa]s?|gilipol{2,}as|cabron(es)?|nazis?|nazistas?|fuck(er|ing)?|shit|bitch)(pro|gamer|master|rey|cine)*$' then return false; end if;
 end loop;
 return true;
end;
$$;
-- END GENERATED TRIVIA NICKNAME POLICY
create table if not exists public.trivia_high_scores (
 id bigint generated always as identity primary key,
 session_id uuid not null unique,
 player_id uuid,
 country_code text check (country_code ~ '^[A-Z]{2}$'),
 age smallint check (age between 1 and 120),
 player_name text not null check (char_length(player_name) between 2 and 24 and player_name = btrim(player_name) and player_name !~ '[[:cntrl:]<>]'),
 score integer not null check (score between 0 and 24750),
 hints_used smallint check (hints_used between 0 and 3),
 correct_count integer not null check (correct_count between 0 and 20),
 created_at timestamptz not null default now()
);
-- Preserve results from the first iteration; all new submissions require a profile.
alter table public.trivia_high_scores add column if not exists player_id uuid;
alter table public.trivia_high_scores add column if not exists country_code text check (country_code ~ '^[A-Z]{2}$');
alter table public.trivia_high_scores add column if not exists age smallint check (age between 1 and 120);
alter table public.trivia_high_scores add column if not exists hints_used smallint check (hints_used between 0 and 3);
alter table public.trivia_high_scores drop constraint if exists trivia_high_scores_score_check;
alter table public.trivia_high_scores add constraint trivia_high_scores_score_check check (score between 0 and 24750);
alter table public.trivia_high_scores drop constraint if exists trivia_high_scores_nickname_policy_check;
alter table public.trivia_high_scores add constraint trivia_high_scores_nickname_policy_check check (public.is_trivia_nickname_allowed(player_name)) not valid;
create index if not exists idx_trivia_high_scores_ranking on public.trivia_high_scores (score desc, created_at asc, id asc);
alter table public.trivia_high_scores enable row level security;
revoke all on public.trivia_high_scores from public, anon, authenticated;
revoke all on sequence public.trivia_high_scores_id_seq from public, anon, authenticated;

drop function if exists public.list_trivia_high_scores(integer);
create function public.list_trivia_high_scores(p_limit integer default 10)
returns table (rank integer, player_name text, country_code text, score integer, correct_count integer)
language sql security definer set search_path = '' as $$
 select row_number() over (order by s.score desc, s.created_at asc, s.id asc)::integer,
 s.player_name, s.country_code, s.score, s.correct_count
 from public.trivia_high_scores s
 where public.is_trivia_nickname_allowed(s.player_name)
 order by s.score desc, s.created_at asc, s.id asc
 limit least(greatest(coalesce(p_limit, 10), 1), 10);
$$;

drop function if exists public.submit_trivia_high_score(uuid, text, jsonb);
drop function if exists public.submit_trivia_high_score(uuid, uuid, text, text, integer, jsonb);
create or replace function public.submit_trivia_high_score(p_session_id uuid, p_player_id uuid, p_player_name text, p_country_code text, p_age integer, p_answers jsonb, p_hints_used integer)
returns table (score integer)
language plpgsql security definer set search_path = '' as $$
declare
 normalized_name text := btrim(coalesce(p_player_name, ''));
 answer jsonb;
 calculated_score integer := 0;
 correct_count integer := 0;
 remaining integer;
 existing_score integer;
 existing_player uuid;
begin
 if p_session_id is null or p_player_id is null or char_length(normalized_name) not between 2 and 24 or normalized_name ~ '[[:cntrl:]<>]' then
  raise exception 'invalid player or session';
 end if;
 if not public.is_trivia_nickname_allowed(normalized_name) then raise exception 'nickname not allowed'; end if;
 if p_country_code is null or p_country_code !~ '^[A-Z]{2}$' or p_age is null or p_age not between 1 and 120 then
  raise exception 'invalid nationality or age';
 end if;
 if p_hints_used is null or p_hints_used not between 0 and 3 then raise exception 'invalid hints count'; end if;
 if p_answers is null or jsonb_typeof(p_answers) <> 'array' then raise exception 'invalid answers'; end if;
 if jsonb_array_length(p_answers) <> 20 then raise exception 'exactly 20 answers required'; end if;
 for answer in select value from jsonb_array_elements(p_answers) loop
  if jsonb_typeof(answer) <> 'object' or jsonb_typeof(answer->'correct') is distinct from 'boolean'
   or jsonb_typeof(answer->'remaining_ms') is distinct from 'number'
   or (answer->>'remaining_ms') !~ '^[0-9]{1,5}$' then raise exception 'invalid answer'; end if;
  remaining := (answer->>'remaining_ms')::integer;
  if remaining not between 0 and 20000 then raise exception 'invalid time'; end if;
  if (answer->>'correct')::boolean then
   if remaining = 0 then raise exception 'expired answer'; end if;
   calculated_score := calculated_score + 1000 + remaining / 100;
   correct_count := correct_count + 1;
  end if;
 end loop;
 calculated_score := calculated_score + (3 - p_hints_used) * 250;
 -- Same completed session can be retried safely after a network failure.
 perform pg_advisory_xact_lock(hashtext(p_session_id::text));
 select s.score, s.player_id into existing_score, existing_player from public.trivia_high_scores s where s.session_id = p_session_id;
 if found then
  if existing_player is distinct from p_player_id then raise exception 'session belongs to another player'; end if;
  return query select existing_score; return;
 end if;
 insert into public.trivia_high_scores(session_id, player_id, player_name, country_code, age, score, correct_count, hints_used)
 values (p_session_id, p_player_id, normalized_name, p_country_code, p_age, calculated_score, correct_count, p_hints_used);
 -- Keep a bounded arcade board, just like the simulator.
 delete from public.trivia_high_scores s where s.id not in (
  select retained.id from public.trivia_high_scores retained order by retained.score desc, retained.created_at asc, retained.id asc limit 100
 );
 return query select calculated_score;
end;
$$;
revoke all on function public.list_trivia_high_scores(integer) from public;
revoke all on function public.submit_trivia_high_score(uuid, uuid, text, text, integer, jsonb, integer) from public, anon, authenticated;
grant execute on function public.list_trivia_high_scores(integer) to anon, authenticated;
-- Kept for administrative history only. Browser scores must use trivia_sessions.sql.
commit;
